create extension if not exists pgcrypto;
create type public.app_role as enum ('public','admin');
create type public.report_run_status as enum ('queued','discovering','verifying','scoring','analysing','synthesising','quality_check','awaiting_approval','publishing','completed','failed','cancelled');
create type public.materiality_class as enum ('critical','significant','watchlist','exclude');

create function public.set_updated_at() returns trigger language plpgsql set search_path='' as $$ begin new.updated_at=now(); return new; end $$;
create function public.is_admin() returns boolean language sql stable security invoker set search_path='' as $$ select coalesce((select auth.jwt()->'app_metadata'->>'role'),'')='admin' $$;

create table public.profiles (id uuid primary key references auth.users(id) on delete cascade, role public.app_role not null default 'public', display_name text, created_at timestamptz not null default now(), updated_at timestamptz not null default now());
create table public.organisations (id uuid primary key default gen_random_uuid(), slug text not null unique, name text not null, legal_name text, sector text not null, jurisdiction text, organisation_type text, current_owner_id uuid references public.organisations(id), is_irish boolean not null default false, active boolean not null default true, metadata jsonb not null default '{}', created_at timestamptz not null default now(), updated_at timestamptz not null default now());
create table public.organisation_aliases (id uuid primary key default gen_random_uuid(), organisation_id uuid not null references public.organisations(id) on delete cascade, alias text not null, valid_from date, valid_to date, created_at timestamptz not null default now(), updated_at timestamptz not null default now(), unique(organisation_id,alias));
create table public.organisation_relationships (id uuid primary key default gen_random_uuid(), from_organisation_id uuid not null references public.organisations(id), to_organisation_id uuid not null references public.organisations(id), relationship_type text not null, status text not null default 'active', announced_at date, effective_from date, effective_to date, source_id uuid, created_at timestamptz not null default now(), updated_at timestamptz not null default now(), check(from_organisation_id<>to_organisation_id));
create table public.ownership_events (id uuid primary key default gen_random_uuid(), buyer_id uuid references public.organisations(id), target_id uuid not null references public.organisations(id), status text not null, announced_at date, completed_at date, source_id uuid, notes text, created_at timestamptz not null default now(), updated_at timestamptz not null default now());
create table public.report_runs (id uuid primary key default gen_random_uuid(), period_start date not null, period_end date not null, report_date date not null, timezone text not null default 'Europe/Dublin', version integer not null default 1 check(version>0), is_rerun boolean not null default false, status public.report_run_status not null default 'queued', workflow_run_id text, approval_token text unique, started_at timestamptz, completed_at timestamptz, approved_at timestamptz, approved_by uuid references auth.users(id), error_message text, projected_cost_eur numeric(12,4), actual_cost_eur numeric(12,4), created_at timestamptz not null default now(), updated_at timestamptz not null default now(), unique(period_start,period_end,version));
create table public.report_run_status_history (id uuid primary key default gen_random_uuid(), report_run_id uuid not null references public.report_runs(id) on delete cascade, status public.report_run_status not null, detail text, created_at timestamptz not null default now());
create table public.agent_runs (id uuid primary key default gen_random_uuid(), report_run_id uuid not null references public.report_runs(id) on delete cascade, agent_name text not null, status text not null, attempt integer not null default 1, model text, openai_trace_id text, openai_response_id text, input_tokens bigint, output_tokens bigint, tool_calls integer, estimated_cost_eur numeric(12,4), duration_ms bigint, items_found integer, sources_used integer, error_message text, started_at timestamptz, completed_at timestamptz, created_at timestamptz not null default now(), updated_at timestamptz not null default now(), unique(report_run_id,agent_name,attempt));
create table public.workflow_steps (id uuid primary key default gen_random_uuid(), report_run_id uuid not null references public.report_runs(id) on delete cascade, agent_run_id uuid references public.agent_runs(id) on delete cascade, step_key text not null, status text not null, attempt integer not null default 1, input_hash text, output jsonb, error_message text, started_at timestamptz, completed_at timestamptz, created_at timestamptz not null default now(), updated_at timestamptz not null default now(), unique(report_run_id,step_key,attempt));
create table public.sources (id uuid primary key default gen_random_uuid(), url text not null, canonical_url text not null unique, title text not null, publisher text not null, source_type text not null, publication_date date, accessed_at timestamptz not null default now(), primary_source boolean not null default false, credibility_tier smallint not null check(credibility_tier between 1 and 8), evidence_classification text, notes text, approved_public boolean not null default false, created_at timestamptz not null default now(), updated_at timestamptz not null default now());
alter table public.organisation_relationships add constraint organisation_relationship_source_fk foreign key(source_id) references public.sources(id);
alter table public.ownership_events add constraint ownership_event_source_fk foreign key(source_id) references public.sources(id);
create table public.candidate_events (id uuid primary key default gen_random_uuid(), report_run_id uuid not null references public.report_runs(id) on delete cascade, dedupe_key text not null, title text not null, sector text not null, event_date date, announcement_date date, source_publication_date date not null, factual_summary text not null, potential_irish_relevance text, evidence_limitations jsonb not null default '[]', discovery_agent text not null, evidence_classification text, included boolean, exclusion_reason text, created_at timestamptz not null default now(), updated_at timestamptz not null default now(), unique(report_run_id,dedupe_key));
create table public.event_organisations (event_id uuid not null references public.candidate_events(id) on delete cascade, organisation_id uuid not null references public.organisations(id), primary key(event_id,organisation_id));
create table public.event_sources (event_id uuid not null references public.candidate_events(id) on delete cascade, source_id uuid not null references public.sources(id), claim text, supports_claim boolean not null default true, primary key(event_id,source_id));
create table public.materiality_scores (id uuid primary key default gen_random_uuid(), report_run_id uuid not null references public.report_runs(id) on delete cascade, event_id uuid not null unique references public.candidate_events(id) on delete cascade, strategic_significance smallint not null check(strategic_significance between 1 and 5), customer_impact smallint not null check(customer_impact between 1 and 5), commercial_impact smallint not null check(commercial_impact between 1 and 5), regulatory_risk_impact smallint not null check(regulatory_risk_impact between 1 and 5), ireland_competitive_relevance smallint not null check(ireland_competitive_relevance between 1 and 5), immediacy smallint not null check(immediacy between 1 and 5), total smallint generated always as (strategic_significance+customer_impact+commercial_impact+regulatory_risk_impact+ireland_competitive_relevance+immediacy) stored, classification public.materiality_class generated always as (case when strategic_significance+customer_impact+commercial_impact+regulatory_risk_impact+ireland_competitive_relevance+immediacy>=22 then 'critical'::public.materiality_class when strategic_significance+customer_impact+commercial_impact+regulatory_risk_impact+ireland_competitive_relevance+immediacy>=17 then 'significant'::public.materiality_class when strategic_significance+customer_impact+commercial_impact+regulatory_risk_impact+ireland_competitive_relevance+immediacy>=12 then 'watchlist'::public.materiality_class else 'exclude'::public.materiality_class end) stored, rationale text not null, created_at timestamptz not null default now(), updated_at timestamptz not null default now());
create table public.board_signals (id uuid primary key default gen_random_uuid(), report_run_id uuid not null references public.report_runs(id) on delete cascade, event_id uuid references public.candidate_events(id), signal text not null, score smallint not null check(score between 1 and 5), rag text not null check(rag in('red','amber','green','grey')), interpretation text not null, created_at timestamptz not null default now(), updated_at timestamptz not null default now());
create table public.strategic_themes (id uuid primary key default gen_random_uuid(), slug text not null unique, name text not null, description text, created_at timestamptz not null default now(), updated_at timestamptz not null default now());
create table public.theme_assessments (id uuid primary key default gen_random_uuid(), report_run_id uuid not null references public.report_runs(id) on delete cascade, theme_id uuid not null references public.strategic_themes(id), evidence_strength text not null, direction text not null check(direction in('accelerating','stable','weakening','emerging')), current_assessment text not null, previous_assessment text, change_from_previous_report text, likely_12_month_effect text, likely_24_month_effect text, ireland_implication text not null, created_at timestamptz not null default now(), updated_at timestamptz not null default now(), unique(report_run_id,theme_id));
create table public.theme_events (theme_id uuid not null references public.strategic_themes(id), event_id uuid not null references public.candidate_events(id) on delete cascade, primary key(theme_id,event_id));
create table public.competitor_updates (id uuid primary key default gen_random_uuid(), report_run_id uuid not null references public.report_runs(id) on delete cascade, event_id uuid not null references public.candidate_events(id), organisation_id uuid not null references public.organisations(id), strategic_theme text, customer_implication text, commercial_implication text, maturity text, created_at timestamptz not null default now(), updated_at timestamptz not null default now());
create table public.digital_benchmarks (id uuid primary key default gen_random_uuid(), report_run_id uuid not null references public.report_runs(id) on delete cascade, event_id uuid references public.candidate_events(id), organisation_id uuid references public.organisations(id), category text not null, customer_value smallint, commercial_impact smallint, maturity smallint, evidence smallint, ireland_relevance smallint, assessment text, created_at timestamptz not null default now(), updated_at timestamptz not null default now());
create table public.ai_initiatives (id uuid primary key default gen_random_uuid(), report_run_id uuid not null references public.report_runs(id) on delete cascade, event_id uuid references public.candidate_events(id), organisation_id uuid not null references public.organisations(id), use_case text not null, maturity text not null, objective text not null, orientation text not null, technology_partner text, claimed_benefit text, realised_benefit_evidence text not null, strategic_relevance text, last_changed date, created_at timestamptz not null default now(), updated_at timestamptz not null default now());
create table public.regulatory_items (id uuid primary key default gen_random_uuid(), report_run_id uuid not null references public.report_runs(id) on delete cascade, event_id uuid references public.candidate_events(id), title text not null, status text not null, announcement_date date, effective_date date, affected_firms text, customer_impact text, business_impact text, digital_implications text, data_implications text, governance_implications text, required_response text, urgency text, created_at timestamptz not null default now(), updated_at timestamptz not null default now());
create table public.customer_signals (id uuid primary key default gen_random_uuid(), report_run_id uuid not null references public.report_runs(id) on delete cascade, event_id uuid references public.candidate_events(id), classification text not null, signal text not null, sample_size integer, market text, methodology text, limitations text, source_id uuid references public.sources(id), created_at timestamptz not null default now(), updated_at timestamptz not null default now());
create table public.strategic_recommendations (id uuid primary key default gen_random_uuid(), report_run_id uuid not null references public.report_runs(id) on delete cascade, category text not null, priority integer not null, action text not null, supporting_signal text not null, expected_business_outcome text not null, expected_customer_outcome text not null, urgency text not null, confidence text not null, first_action text not null, created_at timestamptz not null default now(), updated_at timestamptz not null default now());
create table public.leadership_decisions (id uuid primary key default gen_random_uuid(), report_run_id uuid not null references public.report_runs(id) on delete cascade, decision text not null, why_now text not null, consequence_of_delay text not null, recommended_owner text, recommended_timing text, position smallint not null check(position between 1 and 5), created_at timestamptz not null default now(), updated_at timestamptz not null default now());
create table public.research_questions (id uuid primary key default gen_random_uuid(), report_run_id uuid not null references public.report_runs(id) on delete cascade, question text not null, status text not null default 'open', priority smallint not null default 3, resolved_at timestamptz, created_at timestamptz not null default now(), updated_at timestamptz not null default now());
create table public.watchlist_items (id uuid primary key default gen_random_uuid(), report_run_id uuid not null references public.report_runs(id) on delete cascade, carried_from_id uuid references public.watchlist_items(id), title text not null, status text not null default 'active', resolution text, created_at timestamptz not null default now(), updated_at timestamptz not null default now());
create table public.reports (id uuid primary key default gen_random_uuid(), report_run_id uuid not null unique references public.report_runs(id) on delete cascade, slug text not null unique, title text not null, executive_headline text not null, overall_assessment text not null, content jsonb not null, is_published boolean not null default false, published_at timestamptz, created_at timestamptz not null default now(), updated_at timestamptz not null default now());
create table public.report_sections (id uuid primary key default gen_random_uuid(), report_id uuid not null references public.reports(id) on delete cascade, section_key text not null, position integer not null, content jsonb not null, created_at timestamptz not null default now(), updated_at timestamptz not null default now(), unique(report_id,section_key));
create table public.covering_emails (id uuid primary key default gen_random_uuid(), report_run_id uuid not null unique references public.report_runs(id) on delete cascade, subject text not null, body text not null, generated_at timestamptz not null default now(), created_at timestamptz not null default now(), updated_at timestamptz not null default now());
create table public.notifications (id uuid primary key default gen_random_uuid(), user_id uuid references auth.users(id) on delete cascade, report_run_id uuid references public.report_runs(id) on delete cascade, title text not null, body text, read_at timestamptz, created_at timestamptz not null default now(), updated_at timestamptz not null default now());
create table public.user_feedback (id uuid primary key default gen_random_uuid(), user_id uuid not null references auth.users(id), report_id uuid references public.reports(id) on delete cascade, event_id uuid references public.candidate_events(id), feedback_type text not null, comment text, created_at timestamptz not null default now(), updated_at timestamptz not null default now());
create table public.audit_events (id uuid primary key default gen_random_uuid(), actor_id uuid references auth.users(id), action text not null, entity_type text not null, entity_id uuid, metadata jsonb not null default '{}', created_at timestamptz not null default now());

create index report_runs_status_idx on public.report_runs(status,created_at desc); create index agent_runs_report_idx on public.agent_runs(report_run_id,status); create index events_report_idx on public.candidate_events(report_run_id,included); create index events_dates_idx on public.candidate_events(event_date,announcement_date,source_publication_date); create index event_org_org_idx on public.event_organisations(organisation_id,event_id); create index event_sources_source_idx on public.event_sources(source_id,event_id); create index sources_publication_idx on public.sources(publication_date desc); create index reports_published_idx on public.reports(is_published,published_at desc); create index ai_org_changed_idx on public.ai_initiatives(organisation_id,last_changed desc); create index regulations_urgency_idx on public.regulatory_items(urgency,effective_date); create index notifications_user_unread_idx on public.notifications(user_id,read_at) where read_at is null;

do $$ declare t text; begin foreach t in array array['profiles','organisations','organisation_aliases','organisation_relationships','ownership_events','report_runs','report_run_status_history','agent_runs','workflow_steps','sources','candidate_events','event_organisations','event_sources','materiality_scores','board_signals','strategic_themes','theme_assessments','theme_events','competitor_updates','digital_benchmarks','ai_initiatives','regulatory_items','customer_signals','strategic_recommendations','leadership_decisions','research_questions','watchlist_items','reports','report_sections','covering_emails','notifications','user_feedback','audit_events'] loop execute format('alter table public.%I enable row level security',t); end loop; end $$;

create policy profiles_self_read on public.profiles for select to authenticated using(id=(select auth.uid()) or public.is_admin());
create policy profiles_admin_all on public.profiles for all to authenticated using(public.is_admin()) with check(public.is_admin());
create policy public_reports_read on public.reports for select to anon,authenticated using(is_published);
create policy public_report_sections_read on public.report_sections for select to anon,authenticated using(exists(select 1 from public.reports r where r.id=report_id and r.is_published));
create policy public_sources_read on public.sources for select to anon,authenticated using(approved_public);
create policy public_organisations_read on public.organisations for select to anon,authenticated using(active);
create policy public_aliases_read on public.organisation_aliases for select to anon,authenticated using(exists(select 1 from public.organisations o where o.id=organisation_id and o.active));
create policy public_themes_read on public.strategic_themes for select to anon,authenticated using(true);
do $$ declare t text; begin foreach t in array array['organisations','organisation_aliases','organisation_relationships','ownership_events','report_runs','report_run_status_history','agent_runs','workflow_steps','sources','candidate_events','event_organisations','event_sources','materiality_scores','board_signals','strategic_themes','theme_assessments','theme_events','competitor_updates','digital_benchmarks','ai_initiatives','regulatory_items','customer_signals','strategic_recommendations','leadership_decisions','research_questions','watchlist_items','reports','report_sections','covering_emails','notifications','user_feedback','audit_events'] loop execute format('create policy %I on public.%I for all to authenticated using(public.is_admin()) with check(public.is_admin())','admin_all_'||t,t); end loop; end $$;
create policy notifications_own_read on public.notifications for select to authenticated using(user_id=(select auth.uid())); create policy notifications_own_update on public.notifications for update to authenticated using(user_id=(select auth.uid())) with check(user_id=(select auth.uid()));

do $$ declare t text; begin foreach t in array array['profiles','organisations','organisation_aliases','organisation_relationships','ownership_events','report_runs','agent_runs','workflow_steps','sources','candidate_events','materiality_scores','board_signals','strategic_themes','theme_assessments','competitor_updates','digital_benchmarks','ai_initiatives','regulatory_items','customer_signals','strategic_recommendations','leadership_decisions','research_questions','watchlist_items','reports','report_sections','covering_emails','notifications','user_feedback'] loop execute format('create trigger set_%I_updated_at before update on public.%I for each row execute function public.set_updated_at()',t,t); end loop; end $$;

